document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.publicTransport){const r=PRACTICAL_TRAVEL.system(b.dataset.publicTransport);if(r)openDrawer(r.title,PRACTICAL_TRAVEL.transportBody(r.id));}if(b.dataset.fuel){const day=+b.dataset.fuel;openDrawer(shortDate(DATA.days[day-1].date)+' · 沿途补能',PRACTICAL_TRAVEL.fuelBody(day));}});
